/**
 * Egypt and Return
 * ----------------
 * Famine drives Abram into Egypt, where fear leads him to present Sarai as his sister — and Pharaoh's household pays the price until the truth surfaces. Stage: Nile-side palace gates, Egyptian banners and linen, gold light; Abram returning across the wilderness with restitution, contrite and poorer.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: pillar
 * Game beat: Choose honest repairs after a fearful mistake.
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./abraham-kit.js.
 */

import { THREE, createScene, water, column, throne, pillar, person } from './abraham-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 3276372119, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* river: animated water between grassy banks */
    water(W, group, 260, 26, -0.4, 0x2a2317, 0xb39863);
    W.ground(260, 95, 0, 60, 0x776542, { amp: 0.5, j: 0.3, flat: 24, fz: 54 });
    W.ground(260, 95, 0, -64, 0x655638, { amp: 0.6, j: 0.3, flat: 24, fz: -58 });
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x413824), [0, -0.05, 12.6]);
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x413824), [0, -0.05, -14.6]);

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0xa88f5d, { band: 0xa28a5a });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x8c784e });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 11, 1.15, { stone: 0x9c8456 });
    W.disc([0, 6, -1], 5, 0xffef9c, 0.3);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: -0.61, s: 1.13 });
    person(W, group, [4.5, 0, 17], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: -0.47, s: 1.05 });

    return W.finish();
}

export default { build };
